import { By } from '@angular/platform-browser';
import { ProfileCardComponent } from './profile-card.component';

describe('ProfileCardComponent', () => {
  let component: ProfileCardComponent;
  let fixture: ComponentFixture<ProfileCardComponent>;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [ ProfileCardComponent ]
    })
    .compileComponents();
  });

  beforeEach(() => {
    fixture = TestBed.createComponent(ProfileCardComponent);
    component = fixture.componentInstance;
    component.firstName = 'John';
    component.lastName = 'Doe';
    fixture.detectChanges();
  });

  it('debería mostrar el nombre completo', () => {
    const headerDe = fixture.debugElement.query(By.css('h1'));
    const headerEl = headerDe.nativeElement;

    expect(headerEl.textContent).toBe('John Doe');
  });
});
```

### Explicación del código de la prueba

1. **Configuración del módulo de pruebas**:
